// ============================================================================ // Lookup helpers - every cross-reference is resolved here, by name // ============================================================================
/** * Resolve the scoped application's sys_scope sys_id by its namespace. Returns * an empty string when the application is not installed, which callers treat as * "nothing to remediate". */ function lookupScopeSysId() { var gr = new GlideRecord('sys_scope'); gr.addQuery('scope', SCOPE_NAME); gr.setLimit(1); gr.query(); return gr.next() ? gr.getUniqueValue() : ''; }
