/** * State of the lease this run holds. `mutex` is the platform Mutex object, kept * so the same object releases what it acquired. */ var LEASE = { held: false, mutex: null, acquiredAt: '', node: '' };
/** * Read the lease's backing sys_mutex row. * * Row semantics, measured on the target PDI: * free : acquired = '' system_id = 'available' * held : acquired = <timestamp> system_id = <node id> * The row is created by the platform on first acquisition and is then reused, so * "no row" means the lease has never been taken on this instance. * * @return {Object} { present: boolean, held: boolean, acquired: string, node: string } */ function readLeaseRow() { var gr = new GlideRecord('sys_mutex'); gr.addQuery('name', LEASE_NAME); gr.setLimit(1); gr.query(); if (!gr.next()) { return { present: false, held: false, acquired: '', node: '' }; } var acquired = String(gr.getValue('acquired') || ''); var node = String(gr.getValue('system_id') || ''); return { present: true, held: acquired !== '' && node !== '' && node !== LEASE_FREE_MARKER, acquired: acquired, node: node }; }
/** * Acquire the cluster-wide remediation lease, FAIL CLOSED. * * Why this exists: ensureTable() contains the only destructive step in the * script - it deletes a table's sys_dictionary and sys_db_object rows and * re-inserts them so the platform's own DDL business rule runs. That decision is * taken from a physical-storage probe, so two runs that overlap can both observe * "metadata only, no storage" and interleave the purge and the re-insert, leaving * partially removed metadata or a half-materialised schema. Two runs really can * overlap: the script is drop-in runnable from Scripts - Background, an operator * can start it twice, and an instance carrying an earlier active copy of the * bootstrap trigger can dispatch it while a manual run is in flight. * * The lease is taken BEFORE the first probe and before any write, so no decision * this script makes is ever taken outside it. * * Fail-closed, in three steps: * 1. a NON-BLOCKING check of the backing sys_mutex row. If another node or run * holds the lease, this run refuses immediately and names the holder rather * than queueing behind it - the platform's Mutex.get() spin-waits (measured: * a second caller waited 14.8 s and then acquired), and silently waiting is * exactly what an operator investigating a stuck run must not be given. * 2. Mutex.get(), which closes the race between step 1 and here. Any exception - * including "not allowed in scoped applications" if this body is ever run in * the application scope - is a refusal, not a warning. * 3. a read-back: the row must now report the lease held. If it does not, the * acquisition is not trusted, is released again, and the run refuses. * * @return {Object} { ok: boolean, reason: string } */ function acquireRemediationLease() { var pre = readLeaseRow(); if (pre.held) { return { ok: false, reason: 'another remediation run holds the lease "' + LEASE_NAME + '" (acquired ' + pre.acquired + ' by node ' + pre.node + ')' }; }
var mutex; try { mutex = new GlideMutex(LEASE_NAME); } catch (e) { return { ok: false, reason: 'the platform cluster mutex is unavailable in this context (' + e + '), so the destructive rebuild cannot be serialized' }; }
var got = false; try { got = mutex.get(); } catch (e2) { return { ok: false, reason: 'lease acquisition threw ' + e2 }; } if (got !== true && got !== 'true') { return { ok: false, reason: 'lease acquisition returned ' + got }; }
