/** * Interrogate one physical-storage signal and reduce it to a tri-state. * * @param {string} label signal name, for the trace * @param {Function} fn returns a truthy/falsy verdict, may throw * @return {Object} { state: 'yes'|'no'|'unknown', label: string, note: string } */ function physicalSignal(label, fn) { try { var verdict = fn(); if (verdict === true || verdict === 'true' || verdict === 1 || verdict === '1') { return { state: 'yes', label: label, note: '' }; } if (verdict === false || verdict === 'false' || verdict === 0 || verdict === '0') { return { state: 'no', label: label, note: '' }; } // Anything that is neither a clean true nor a clean false (null, // undefined, an object, a changed return type on a future release) is // NOT evidence of absence. return { state: 'unknown', label: label, note: 'non-boolean verdict "' + verdict + '"' }; } catch (e) { return { state: 'unknown', label: label, note: '' + e }; } }
/** * Determine whether `tableName` has physical storage, as a TRI-STATE. * * This function guards a destructive branch (ensureTable() deletes a table's * metadata rows before rebuilding it), so it must never answer "no storage" * because a probe failed. Three independent platform signals are interrogated; * each was measured on the target PDI against a physical scoped table, a * metadata-only table produced by a workflow-suppressed `sys_db_object` insert, * and a table name that does not exist at all: * * signal physical | metadata-only | absent * GlideTableDescriptor.isValid true | false | false * new GlideRecord(t).isValid() true | false | false * new TableUtils(t).tableExists()true | false | false * * (`GlideRecord.isValidField('sys_id')` and `GlideTableDescriptor.get().getName()` * were also measured and answer identically in all three cases, so they carry no * information and are not used.) * * Reduction rules, in order: * - ANY signal reporting 'yes' -> 'yes'. One positive is enough: destroying * the metadata of a table that does have storage would drop live data, so * the benign outcome (do nothing) wins every disagreement. * - ALL THREE reporting 'no' -> 'no'. Only unanimous agreement is accepted * as positive proof that there is nothing to destroy. * - anything else -> 'unknown', and the caller must abort. * * @param {string} tableName table to probe * @return {Object} { state: 'yes'|'no'|'unknown', detail: string } */ function probePhysicalState(tableName) { var signals = [ physicalSignal('GlideTableDescriptor.isValid', function () { return GlideTableDescriptor.isValid(tableName); }), physicalSignal('GlideRecord.isValid', function () { return new GlideRecord(tableName).isValid(); }), physicalSignal('TableUtils.tableExists', function () { return new TableUtils(tableName).tableExists(); }) ];
