/** * Count the physical columns of a table, for the verification trace. * * GlideTableDescriptor.getElements() returns undefined on this release, so the * count is taken from a GlideRecord's own element list, which is the field layer * the application actually reads through. Returns -1 when the table has no * physical storage. */ function physicalColumnCount(tableName) { if (!tableIsPhysical(tableName)) { return -1; } try { var gr = new GlideRecord(tableName); gr.initialize(); var elements = gr.getElements(); return elements ? parseInt('' + elements.size(), 10) : -1; } catch (e) { return -1; } }
