ete' + ' (deleted=' + objPurge.deleted + ',refused=' + objPurge.refused + ',rows_remaining=' + objPurge.residue + ').'); return false; } log('TABLE|' + spec.name + '|clean slate|dictionary_rows_removed=' + dictPurge.deleted + '|db_object_rows_removed=' + objPurge.deleted + '|residue=0|reusing_sys_id=' + (carried.sysId ? 'yes' : 'no'));
