/** * Ensure a scripted REST definition carries its service_id, which is the URL * path segment. Without it the route collapses to /api/<namespace> and every * call returns HTTP 400 "Requested URI does not represent any resource". * * APPLICATION CONFINEMENT. `sys_ws_definition.name` is a display name and is not * unique across the instance: this PDI alone carries several definitions whose * names and service_ids repeat across scopes ("Get Applications" and "ServiceNow * Studio Applications API" both answer to service_id `applications`). Resolving * "Case Submit" by name alone would therefore let this script REWRITE THE ROUTE * of another application's endpoint. The query is anchored on this application's * sys_scope, the candidate's sys_package is checked too, and exactly one row may * match - two matches are reported and neither is touched, because there is no * safe way to choose. * * Idempotency: writes only when the stored value differs. * * @param {Object} spec one entry of REST_SPECS * @param {string} scopeSysId the application scope, resolved by name */ function ensureServiceId(spec, scopeSysId) { var gr = new GlideRecord('sys_ws_definition'); gr.addQuery('name', spec.name); gr.addQuery('sys_scope', scopeSysId); gr.query(); var candidates = []; while (gr.next()) { candidates.push({ sysId: gr.getUniqueValue(), serviceId: String(gr.getValue('service_id') || ''), baseUri: String(gr.getValue('base_uri') || ''), // NOT named `package`: that is a FutureReservedWord, and Rhino refuses // the whole file with "invalid property id" when it is used as a // property name (measured - the script would not compile at all). packageId: String(gr.getValue('sys_package') || '') }); } if (candidates.length === 0) { logError('REST|' + spec.name + '|no sys_ws_definition record named "' + spec.name + '" in scope ' + SCOPE_NAME + '. A record of that name elsewhere on the instance is deliberately NOT used:' + ' rewriting another application\'s endpoint route is exactly what this constraint prevents.'); return; } if (candidates.length > 1) { var ids = []; for (var i = 0; i < candidates.length; i++) { ids.push(candidates[i].sysId); } logError('REST|' + spec.name + '|' + candidates.length + ' sys_ws_definition records in scope ' + SCOPE_NAME + ' carry this name (' + ids.join(',') + '). None was modified - there is no safe way' + ' to choose. Recovery: delete the duplicate and re-run.'); return; } var match = candidates[0]; if (match.packageId && match.packageId !== scopeSysId) { logError('REST|' + spec.name + '|the record in scope ' + SCOPE_NAME + ' (' + match.sysId + ') belongs to package ' + match.packageId + ' rather than this application. Not modified.'); return; } if (match.serviceId === spec.serviceId) { STATS.serviceIdsAlready++; log('REST|' + spec.name + '|already correct|service_id=' + spec.serviceId + '|base_uri=' + match.baseUri + '|scope=' + SCOPE_NAME); return; }
var write = new GlideRecord('sys_ws_definition'); if (!write.get(match.sysId)) { logError('REST|' + spec.name + '|record ' + match.sysId + ' disappeared before the write'); return; } write.setValue('service_id', spec.serviceId); write.update();
var check = new GlideRecord('sys_ws_definition'); check.get(match.sysId); if (String(check.getValue('service_id') || '') !== spec.serviceId) { logError('REST|' + spec.name + '|service_id write did not stick|stored=' + String(check.getValue('service_id') || '')); return; } STATS.serviceIdsSet++; log('REST|' + spec.name + '|set|service_id=' + check.getValue('service_id') + '|base_uri=' + (check.getValue('base_uri') || '') + '|scope=' + SCOPE_NAME); }
// ============================================================================ // Defect 9 - ACL to role link records, plus the security-cache flush // ============================================================================
/** * Read an ACL's required roles from the deliverable's own committed payload. * * This is the primary and authoritative source. Every ACL artifact in * ../acl/*.xml - and therefore every `<type>ACL</type>` block in the Update Set * - carries a `<roles>` element naming the role(s) that ACL grants, by NAME: * * <roles>x_casemgmt_case_manager</roles> * <roles>x_casemgmt_case_manager,x_casemgmt_case_agent</roles> * * `sys_security_acl` has no `roles` column on this release, so the element is * ignored when the record itself is written - but the update engine stores the * incoming payload verbatim as a `sys_update_version` row keyed * `sys_security_acl_<sys_id>`. That row is therefore a durable, on-instance, * name-based copy of the package's own declaration, and reading it back is what * makes this mapping immune to the failure mode described in rolesForAcl(). * Across the 26 shipped ACLs the `<roles>` elements total exactly * EXPECTED_ACL_ROLE_LINKS links. * * Versions are scanned newest-first rather than only `state=current`, because a * later hand-edit of the ACL in the UI writes a fresh version from the * platform's own serialization, which - having no `roles` column to serialize - * carries no `<roles>` element. Walking back to the most recent payload that * does declare roles recovers the package's intent in that case too. * * No sys_id is hard-coded: the version row is located from the ACL sys_id read * out of the database in this same run, and the roles it yields are names. * * @param {string} aclSysId the ACL, resolved in this run * @return {Array} role names declared by the package, possibly empty */ function rolesFromCommittedPayload(aclSysId) { var gr = new GlideRecord('sys_update_version'); gr.addQuery('name', 'sys_security_acl_' + aclSysId); gr.orderByDesc('sys_created_on'); gr.query(); while (gr.next()) { var payload = gr.getValue('payload') || ''; var match = /<roles>([\s\S]*?)<\/roles>/.exec(payload); if (!match) { continue; } var declared = match[1]