/** * The sys_id this installer gives the link for one (ACL, role) pair. * * THIS IS THE PROVENANCE MARKER, and it has to be the primary key because every * other candidate is platform-managed. `sys_name` was tried first and is NOT * usable: the platform's own business rule "Update ACL Description on Role * Change" rewrites `sys_security_acl_role.sys_name` to '<acl name>.<role name>' * on insert, whoever inserts it - measured directly, a hand-made row inserted * with sys_name 'hand made by an administrator' was read back carrying * 'x_casemgmt_case.x_casemgmt_case_agent'. `sys_scope`, `sys_created_by` and the * timestamps are equally indistinguishable: a role added through the UI while the * application picker is set to this application carries the same scope and the * same creating user as this script. * * The sys_id, by contrast, is chosen by whoever inserts the row. A row created * here carries the value below; a row created by an administrator, by a newer * version of this application or by another automation carries a random GUID and * can therefore never be mistaken for one of ours. * * The derivation is the first 16 hex characters of the ACL's sys_id followed by * the first 16 of the role's sys_id: deterministic, reproducible from the row * itself, and 128 bits wide, so it is unique per pair. It carries no hard-coded * literal - both halves are read out of the database in the same run. * * @param {string} aclSysId the ACL, resolved in this run * @param {string} roleSysId the role, resolved by name in this run * @return {string} the 32-character identity, or '' when either input is unusable */ function installerLinkSysId(aclSysId, roleSysId) { var acl = String(aclSysId || ''); var role = String(roleSysId || ''); if (!/^[0-9a-f]{32}$/.test(acl) || !/^[0-9a-f]{32}$/.test(role)) { return ''; } return acl.substring(0, 16) + role.substring(0, 16); }
/** * Ensure one ACL -> role link exists. * * Idempotency: keyed on (sys_security_acl, sys_user_role), so a re-run inserts * nothing. Both sides are sys_ids read from the database in this same run - the * ACL by its own name/description scan, the role by name - so no sys_id is * hard-coded anywhere. * * @param {string} aclSysId ACL resolved in this run * @param {string} aclName for the trace and for sys_name * @param {string} roleName role to require * @param {Object} roleIds map of roleName -> sys_id resolved by name * @param {string} scopeSysId the application scope, resolved by name */ function ensureAclRoleLink(aclSysId, aclName, roleName, roleIds, scopeSysId) { var roleSysId = roleIds[roleName]; if (!roleSysId) { logError('ACL_LINK|' + aclName + '|role not found: ' + roleName); return; }
var existing = new GlideRecord('sys_security_acl_role'); existing.addQuery('sys_security_acl', aclSysId); existing.addQuery('sys_user_role', roleSysId); existing.query(); if (existing.hasNext()) { STATS.aclLinksAlready++; return; }
