/** * Reconcile the live `sys_security_acl_role` rows with the expected pair set: * create every expected pair that is missing, and deal with every pair that is * not expected. * * Both directions matter. A missing pair leaves an ACL with no role, which on a * high-security instance evaluates to deny and locks every non-admin out. A * surplus pair silently widens access. Convergence therefore means the live set * EQUALS the expected set, and the caller requires the total to be exactly * EXPECTED_ACL_ROLE_LINKS - not "at least". * * OWNERSHIP RULE for the surplus direction. Every surplus pair is REPORTED as an * error, so the run reports verified=false and an operator sees it. Only a pair * this installer demonstrably created (installerOwnsLink) is deleted; a pair * created by an administrator, by a newer version of this application or by * another automation is left exactly as it is, with its sys_id and the reason * printed, because a security grant this script did not create is not its to * destroy. Deletions are verified the same way every other delete in this script * is: the return value is checked and the row is read back. * * @param {string} scopeSysId the application scope, resolved by name * @return {Object} { total: number, byRole: Object, expected: Object, * extras: Array, missing: Array } */ function ensureAllAclRoleLinks(scopeSysId) { var roleIds = {}; roleIds[ROLE_MANAGER] = lookupRoleSysId(ROLE_MANAGER); roleIds[ROLE_AGENT] = lookupRoleSysId(ROLE_AGENT); roleIds[ROLE_VIEWER] = lookupRoleSysId(ROLE_VIEWER); log('ACL_LINK|roles resolved by name|manager=' + (roleIds[ROLE_MANAGER] ? 'yes' : 'NO') + '|agent=' + (roleIds[ROLE_AGENT] ? 'yes' : 'NO') + '|viewer=' + (roleIds[ROLE_VIEWER] ? 'yes' : 'NO'));
