// 2. deal with the live pairs that are NOT expected. The candidate set is // every link on one of this application's ACLs, plus every link recorded in // this application's scope - so a stray row is caught from either side. // Every one of them is REPORTED; only rows this installer created are // deleted (see installerOwnsLink). var appRoleNames = {}; var roleName; for (roleName in roleIds) { if (roleIds.hasOwnProperty(roleName) && roleIds[roleName]) { appRoleNames[roleIds[roleName]] = roleName; } } var extras = []; var seen = {}; var candidates = [ { field: 'sys_security_acl.name', op: 'STARTSWITH', value: SCOPE_NAME, label: 'by ACL name' }, { field: 'sys_scope', op: '=', value: scopeSysId, label: 'by scope' } ]; for (i = 0; i < candidates.length; i++) { var link = new GlideRecord('sys_security_acl_role'); if (candidates[i].op === 'STARTSWITH') { link.addQuery(candidates[i].field, 'STARTSWITH', candidates[i].value); } else { link.addQuery(candidates[i].field, candidates[i].value); } link.query(); while (link.next()) { var id = link.getUniqueValue(); if (seen[id]) { continue; } seen[id] = true; var pairKey = link.getValue('sys_security_acl') + '|' + link.getValue('sys_user_role'); if (expected.pairs.hasOwnProperty(pairKey)) { continue; } var ownership = installerOwnsLink(link, scopeSysId, appRoleNames); var label = ownership.label + ' [sys_id=' + id + ']';
