// 3. report the reconciled state, read back from the database var live = liveAclRolePairs(scopeSysId); var missing = []; for (i = 0; i < expectedKeys.length; i++) { if (!live.pairs.hasOwnProperty(expectedKeys[i])) { missing.push(expected.labels[expectedKeys[i]]); } } log('ACL_LINK|acls_scanned=' + expected.aclCount + '|links_created=' + STATS.aclLinksCreated + '|links_already_present=' + STATS.aclLinksAlready + '|installer_owned_links_removed=' + STATS.aclLinksRemoved + '|foreign_links_reported_not_removed=' + STATS.aclLinksReported + '|links_total_in_scope=' + live.total + '|expected=' + expectedKeys.length + '|by_role=' + describeCounts(live.byRole)); for (i = 0; i < missing.length; i++) { logError('ACL_LINK|expected link still absent after reconciliation: ' + missing[i]); } return { total: live.total, byRole: live.byRole, expectedCount: expectedKeys.length, extras: extras, missing: missing }; }
/** * Read the live ACL -> role pair set back out of the database. * * @param {string} scopeSysId the application scope, resolved by name * @return {Object} { pairs: Object keyed 'aclSysId|roleSysId', total: number, byRole: Object } */ function liveAclRolePairs(scopeSysId) { var pairs = {}; var byRole = {}; var roleNames = {}; var role = new GlideRecord('sys_user_role'); role.addQuery('name', 'STARTSWITH', SCOPE_NAME); role.query(); while (role.next()) { roleNames[role.getUniqueValue()] = role.getValue('name'); }
